using System;using System.IO;using IslandGame;using Newtonsoft.Json.Linq;
public static class VerifyContactBarrier {
 static JObject Frame(float at,int session=1){return new JObject{{"id","hitch-"+session},{"routeStage","mount"},{"room",0},{"elapsed",at},{"hero",new JObject{{"action","attack1"},{"motion",new JObject{{"kind","attack"},{"attackId",1},{"start",0},{"duration",.55}}}}},{"mobs",new JArray()},{"fx",at<.3f?new JArray():new JArray(new JObject{{"id",1},{"kind","damage"},{"attackId",1},{"contactAt",.22f}},new JObject{{"id",2},{"kind","damage"},{"attackId",1},{"contactAt",.26f}})}};}
 public static object Run(){var buffer=new CombatSnapshotBuffer();int checks=0;buffer.Sample(Frame(0),0,true);buffer.Sample(Frame(.2f),.2,true);var f=Frame(.5f);var r=buffer.Sample(f,.5,true);if(Math.Abs(buffer.Time-.22f)>.00001f)throw new Exception("Frame hitch skipped first contact: "+buffer.Time);checks++;if((int)r["hero"]["motion"]["attackId"]!=1)throw new Exception("Wrong impact motion");checks++;
 buffer.Sample(f,.5167,true);if(Math.Abs(buffer.Time-.26f)>.00001f)throw new Exception("Skipped second target contact");checks++;buffer.Sample(f,.5333,true);if(buffer.Time<=.26f)throw new Exception("Duplicate contact stalls playback");checks++;float previous=buffer.Time;buffer.Sample(f,.55,true);if(buffer.Time<previous)throw new Exception("Rewound playback");checks++;
 buffer.Sample(f,.6,false);if(buffer.Time!=.5f)throw new Exception("Pause did not snap");checks++;buffer.Sample(Frame(.5f,2),.7,true);if(buffer.Time!=.5f)throw new Exception("Session reset replayed old contact");checks++;
 var result=new {status="PASS",checks,scope="266ms render hitch, two target contacts, no rewind/duplicate, pause, session reset"};File.WriteAllText("C:/Users/SHK/combo-deploy-20261109/evidence/contact-barrier.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}
}
